package io.github.diodeme.ji.ai;

import java.util.Map;

/** Provider-neutral content blocks used by transcript and stream events. */
public sealed interface Content permits Content.Text, Content.ToolCall {
    record Text(String text) implements Content {
        public Text {
            if (text == null) throw new IllegalArgumentException("text must not be null");
        }
    }

    record ToolCall(String id, String name, Map<String, Object> arguments) implements Content {
        public ToolCall {
            requireText(id, "tool call id");
            requireText(name, "tool name");
            arguments = Map.copyOf(arguments);
        }
    }

    private static void requireText(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
    }
}
